// Sales report. Used by the finance export (export.js) and the weekly digest (digest.js).
// The layout is parsed by the finance team's import, so do not move columns around.
// TODO: US region once the tax rules are clear

const PRODUCT_WIDTH = 20;
const UNITS_WIDTH = 5;
const MONEY_WIDTH = 14;
const BULK_DISCOUNT_MIN_UNITS = 100;
const BULK_DISCOUNT_FACTOR = 0.95;
const LARGE_ORDER_THRESHOLD = 10000;
const MONTH_PATTERN = /^\d{4}-\d{2}$/;

// The three groupers deliberately differ in how they treat a leading '-'
// (negative line amounts); the finance import has always received that output.
function groupWithDots(integerPart) {
  let grouped = '';
  for (let i = 0; i < integerPart.length; i++) {
    if (i > 0 && (integerPart.length - i) % 3 === 0) {
      grouped += '.';
    }
    grouped += integerPart[i];
  }
  return grouped;
}

function groupWithSpaces(integerPart) {
  return integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
}

function groupWithCommas(integerPart) {
  const chunks = [];
  const reversed = integerPart.split('').reverse();
  for (let i = 0; i < reversed.length; i += 3) {
    chunks.unshift(reversed.slice(i, i + 3).reverse().join(''));
  }
  return chunks.join(',');
}

// Order of this table is the order of the sections in the report.
const REGIONS = [
  {
    code: 'DE',
    title: 'Germany',
    taxRate: 0.19,
    formatLineAmount: ([whole, cents]) => groupWithDots(whole) + ',' + cents + ' €',
  },
  {
    code: 'FR',
    title: 'France',
    taxRate: 0.2,
    formatLineAmount: ([whole, cents]) => groupWithSpaces(whole) + ',' + cents + ' €',
  },
  {
    code: 'UK',
    title: 'United Kingdom',
    taxRate: 0.2,
    formatLineAmount: ([whole, cents]) => '£' + groupWithCommas(whole) + '.' + cents,
  },
];

export function formatMoney(amount, region) {
  let sign = '';
  if (amount < 0) {
    sign = '-';
    amount = -amount;
  }
  const fixed = amount.toFixed(2);
  const whole = fixed.slice(0, fixed.length - 3);
  const cents = fixed.slice(-2);
  const groups = [];
  for (let i = whole.length; i > 0; i -= 3) {
    groups.unshift(whole.slice(Math.max(0, i - 3), i));
  }
  if (region === 'DE') {
    return sign + groups.join('.') + ',' + cents + ' €';
  }
  if (region === 'FR') {
    return sign + groups.join(' ') + ',' + cents + ' €';
  }
  if (region === 'UK') {
    return sign + '£' + groups.join(',') + '.' + cents;
  }
  throw new Error('unknown region: ' + region);
}

export function buildReport(sales, options) {
  options = options || {};
  validateOptions(options);

  const rows = selectRows(sales, options.month);
  const totals = { rows: 0, largeOrders: 0 };

  const lines = [options.month ? 'SALES REPORT ' + options.month : 'SALES REPORT', ''];
  for (const region of REGIONS) {
    lines.push(...buildRegionSection(region, rows, totals));
  }

  if (totals.rows === 0) {
    lines.push('No sales.');
  } else {
    lines.push('Rows: ' + totals.rows);
    lines.push('Large orders: ' + totals.largeOrders);
  }
  return lines.join('\n') + '\n';
}

function validateOptions(options) {
  if (options.format && options.format !== 'text') {
    throw new Error('unsupported format: ' + options.format);
  }
  if (options.month && !MONTH_PATTERN.test(options.month)) {
    throw new Error('bad month: ' + options.month);
  }
}

function selectRows(sales, month) {
  let rows = sales.slice();
  if (month) {
    rows = rows.filter((sale) => sale.date.slice(0, 7) === month);
  }
  return rows.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
}

// Returns the section's lines (empty when the region has no sales) and
// adds the section's row and large-order counts to `totals`.
function buildRegionSection(region, rows, totals) {
  const regionSales = rows.filter((sale) => sale.region === region.code && sale.units > 0);
  if (regionSales.length === 0) {
    return [];
  }

  const lines = ['== ' + region.title + ' =='];
  let subtotal = 0;
